function startImportReview(){
 const text=$('#importText').value,title=$('#importTitle').value.trim(),source=sourceURL($('#importSource').value);
 importBatch=documentDrafts(text,title,$('#splitSections').checked).map(draft=>prepareDraft({...draft,region:activeRegion||regions[0],condition:''}));
 importMetadata={documentTitle:title||importBatch[0].name,source,importedAt:new Date().toISOString(),...textFileMetadata};
 view='import-review';query='';render();
}
function importReview(){return `<div class="page-head">${kicker('Document review')}<h1>Review imported entries</h1><p class="lede small">Source text is preserved. Fields are filled only from labels already in your document; nothing is inferred or reworded. Imported entries are marked unreviewed. Nothing is saved until you confirm.</p><p class="row-meta">Document: ${escapeHTML(importMetadata.documentTitle)} · Source: ${escapeHTML(importMetadata.source||'Not supplied')}</p></div><form id="batchForm" class="form">${importBatch.map((draft,index)=>`<section class="panel draft" data-draft="${index}"><div class="draft-head"><span class="num">${String(index+1).padStart(2,'0')}</span><p class="row-meta">Source: ${escapeHTML(draft.metadata?.documentTitle||importMetadata.documentTitle)} · ${escapeHTML(draft.metadata?.source||importMetadata.source||'Local file or pasted text')}</p></div><div class="field"><label>Entry title</label><input name="title-${index}" value="${escapeHTML(draft.name)}" required maxlength="160"></div><div class="two"><div class="field"><label>Body region</label><select name="region-${index}">${regions.map(region=>`<option ${region===draft.region?'selected':''}>${escapeHTML(region)}</option>`).join('')}</select></div><div class="field"><label>Condition (optional)</label><input name="condition-${index}" value="${escapeHTML(draft.condition)}"></div></div>${draftFields(draft,index)}<div class="field"><label>${draft.fields&&Object.keys(draft.fields).length?'Remaining notes (unlabelled text)':'Imported source text'}</label><textarea name="notes-${index}">${escapeHTML(draft.notes)}</textarea></div><div class="field"><label>Duplicate handling</label><select name="decision-${index}"><option value="skip">Skip if title and region already exist</option><option value="new">Create a separate entry</option><option value="merge">Append the full source text to the matching entry's notes (confirmation required)</option></select></div><p class="row-meta">${duplicateEntries(draft,items).length} existing title/region matches before edits. Matches are checked again when saving.</p><label class="toggle"><input type="checkbox" name="include-${index}" checked><span>Include this entry</span></label></section>`).join('')}<div class="actions sticky-actions">${btn('Confirm import','commit-batch','primary')}${btn('Cancel import','cancel-batch','ghost')}</div></form>`}
async function commitImportReview(){
 const form=$('#batchForm');if(!form.reportValidity())return;
 const data=new FormData(form),planned=[],working=[...items];let skipped=0,merged=0;
 for(let index=0;index<importBatch.length;index++){
  if(!data.has('include-'+index)){skipped++;continue}
  const draft={name:String(data.get('title-'+index)),region:String(data.get('region-'+index)),condition:String(data.get('condition-'+index)),notes:String(data.get('notes-'+index)),sourceText:importBatch[index].sourceText,fields:readDraftFields(data,index)};
  const matches=duplicateEntries(draft,working),decision=data.get('decision-'+index);
  if(matches.length&&decision==='skip'){skipped++;continue}
  if(matches.length>1&&decision==='merge')throw Error('Multiple entries match “'+draft.name+'”. Choose create separate or skip.');
  const metadata=importBatch[index].metadata||importMetadata;
  let record=importRecord(draft,{...metadata,id:uid()});
  if(matches.length&&decision==='merge'){
   const old=matches[0];record={...old,notes:[old.notes,'Imported from '+(metadata.source||metadata.documentTitle)+' on '+metadata.importedAt,draft.sourceText||draft.notes].filter(Boolean).join('\n\n'),updated:record.updated,reviewStatus:'unreviewed',importHistory:JSON.stringify([...readImportHistory(old.importHistory),{...metadata}])};merged++;
   const prior=planned.findIndex(entry=>entry.id===old.id);if(prior!==-1)planned.splice(prior,1);
   working.splice(working.findIndex(entry=>entry.id===old.id),1);
  }
  planned.push(record);working.push(record);
 }
 if(!planned.length){msg('No entries to import. '+skipped+' skipped.');return}
 if(!confirm('Save '+planned.length+' entries? '+merged+' merges append imported text; '+skipped+' skipped. Existing structured fields are preserved.'))return;
 const tx=db.transaction('interventions','readwrite');for(const record of planned)tx.objectStore('interventions').put(record);await transactionDone(tx);
 importBatch=[];textFileMetadata={};view='library';await reload();msg('Imported '+planned.length+' entries locally; '+skipped+' skipped.');
}

function readImportHistory(value){try{const history=JSON.parse(value||'[]');return Array.isArray(history)?history.filter(entry=>entry&&typeof entry==='object'&&!Array.isArray(entry)):[]}catch{return []}}

function readGoogleConfiguration(){try{return JSON.parse(localStorage.getItem('atlas-google-config')||'{}')||{}}catch{return {}}}
// Site-wide Google settings (site-config.mjs) apply to every visitor; a browser may override them with its own project.
function siteGoogleConfig(){try{return validateGoogleConfig(SITE_CONFIG?.google||{})}catch{return null}}
function activeGoogleConfig(){const browser=readGoogleConfiguration();if(browser.clientId){try{return {config:validateGoogleConfig(browser),source:'browser'}}catch{}}const site=siteGoogleConfig();return site?{config:site,source:'site'}:null}
function googleSetupText(){const active=activeGoogleConfig();return !active?'Google isn’t set up for this site yet. The site owner adds public credentials to site-config.mjs (see GOOGLE_SETUP.md), or you can enter your own project below.':active.source==='site'?'Google is set up for this site.':'Using the Google project saved in this browser.'}
const linkedGoogleEntries=()=>items.filter(x=>x.sourceType==='google-doc'&&x.sourceDocumentId);
function googleImportPanel(){const config=readGoogleConfiguration(),linked=new Set(linkedGoogleEntries().map(x=>x.sourceDocumentId)).size;return `<div class="panel"><h2>${icon('library',20)} Connect Google Docs</h2><p class="muted">Choose up to ${MAX_DOCS} Google Docs at a time. Open a folder in the picker and select the documents inside it. Only files you select are shared with PT Atlas. Internet is required to connect and read documents; reviewed imports work offline afterward. Google libraries load only when you click a Google button.</p><details><summary>Google connection setup</summary><p class="muted">Only needed if this site isn’t set up for Google, or to use your own Google Cloud project in this browser. Enter public values only; never a client secret. See GOOGLE_SETUP.md in the repository.</p><div class="field"><label for="googleClientId">Web OAuth client ID</label><input id="googleClientId" value="${escapeHTML(config.clientId||'')}" autocomplete="off"></div><div class="field"><label for="googleApiKey">Picker API key</label><input id="googleApiKey" value="${escapeHTML(config.apiKey||'')}" autocomplete="off"></div><div class="field"><label for="googleProjectNumber">Google Cloud project number</label><input id="googleProjectNumber" value="${escapeHTML(config.projectNumber||'')}" inputmode="numeric"></div>${btn('Save Google setup','save-google','ghost')}</details><label class="toggle"><input type="checkbox" id="googleSplit"><span>Split Google Doc headings into entries</span></label><div class="actions">${btn('Choose Google Docs','choose-google','primary')}${linked?btn('Check imported Docs for updates','google-sync','ghost','history'):''}${btn('Disconnect Google','disconnect-google','ghost')}${config.clientId?btn('Clear browser setup','clear-google','ghost'):''}</div><p id="googleStatus" class="muted" role="status" aria-live="polite">${googleSetupText()}</p><p class="row-meta">${linked?`${plural(linked,'Google Doc')} linked to your library. Updates are never applied without your review. `:''}Access tokens stay in memory and expire. Disconnect revokes the current token; to remove all previously granted access, use your Google Account connections settings. PT Atlas only reads documents and never modifies them in Drive.</p></div>`}
function googleStatus(message){for(const status of document.querySelectorAll('#googleStatus,#googleAccountStatus'))status.textContent=message;}
function saveGoogleConfiguration(){try{const config=validateGoogleConfig({clientId:$('#googleClientId').value,apiKey:$('#googleApiKey').value,projectNumber:$('#googleProjectNumber').value});disconnectGoogle();localStorage.setItem('atlas-google-config',JSON.stringify(config));render();googleStatus('Google setup saved in this browser. Choose Google Docs to continue.');}catch(error){googleStatus(error.message)}}
async function startGoogleImport(button){
 const container=button.closest('.panel');
 try{
  if(!navigator.onLine)throw Error('Google import needs an internet connection. Local files and your saved library remain available offline.');
  const config=requireGoogleConfig();
  button.disabled=true;
  if(!googleReady()){googleStatus('Loading Google connection…');await prepareGoogle();if(container.isConnected)googleStatus('Google connection ready. Click Choose Google Docs again to sign in and open the picker.');return;}
  const split=$('#googleSplit').checked;googleStatus('Choose documents in Google. Selected content will open for review.');
  const documents=await chooseGoogleDocuments(config,{split});
  if(!container.isConnected)return;
  if(!documents.length){googleStatus('Selection cancelled. Nothing was imported.');return;}
  const drafts=documents.flatMap(document=>documentDrafts(document.text,document.metadata.documentTitle,document.split).map(draft=>prepareDraft({...draft,region:activeRegion||regions[0],condition:'',metadata:document.metadata})));
  if(drafts.length>100)throw Error('This selection creates more than 100 entries. Choose fewer documents or turn off heading splitting.');
  importBatch=drafts;importMetadata={documentTitle:documents.length+' selected Google Docs',source:''};view='import-review';query='';render();
 }catch(error){if(container.isConnected)googleStatus('Google import failed: '+error.message);}
 finally{if(button.isConnected)button.disabled=false;}
}

