let pendingCollectionAdd=null;
const pad=n=>String(n).padStart(2,'0');
const colIds=col=>Array.isArray(col.interventionIds)?col.interventionIds:[];
const colItems=col=>colIds(col).map(id=>items.find(i=>i.id===id)).filter(Boolean);
function phaseCard(ph,i,count){const linked=(Array.isArray(ph.interventionIds)?ph.interventionIds:[]).map(id=>items.find(x=>x.id===id)).filter(Boolean);const name=escapeHTML(ph.name);return `<li class="phase"><span class="phase-num" aria-hidden="true">${i+1}</span><div class="phase-body"><div class="phase-title"><div>${kicker('Phase '+(i+1)+(ph.timeframe?' · '+escapeHTML(ph.timeframe):''))}<h3>${name}</h3></div><div class="phase-actions"><button type="button" class="iconbtn" data-action="phase-up" data-phase="${escapeHTML(ph.id)}" aria-label="Move ${name} earlier" ${i===0?'disabled':''}>${icon('up')}</button><button type="button" class="iconbtn" data-action="phase-down" data-phase="${escapeHTML(ph.id)}" aria-label="Move ${name} later" ${i===count-1?'disabled':''}>${icon('down')}</button><button type="button" class="btn ghost small" data-action="edit-phase" data-phase="${escapeHTML(ph.id)}" aria-label="Edit ${name}">${icon('edit',16)}Edit</button></div></div><dl class="phase-grid">${[['Objectives',ph.objectives],['Restrictions & precautions',ph.restrictions],['Criteria to progress',ph.criteria]].map(([t,v])=>`<div><dt>${t}</dt><dd>${v?md(v):'<span class="placeholder">Not recorded</span>'}</dd></div>`).join('')}</dl>${linked.length?`<div class="chips"><span class="row-meta">Interventions:</span>${linked.map(x=>`<button type="button" class="chip chip-link" data-open="${escapeHTML(x.id)}">${escapeHTML(x.name)}</button>`).join('')}</div>`:''}<p class="row-meta">Source: ${escapeHTML(ph.source||'Not recorded')}${ph.sourceDate?' · '+escapeHTML(ph.sourceDate):''}</p></div></li>`}
function phaseEditor(){const c=conditionById(phaseEdit?.conditionId);if(!c)return library();const ph=phases.find(p=>p.id===phaseEdit.phaseId)||{};const chosen=new Set(Array.isArray(ph.interventionIds)?ph.interventionIds:[]);const options=conditionEntries(c);return `<div class="page-head">${kicker(escapeHTML(c.name),c.region)}<h1>${ph.id?'Edit':'New'} protocol phase</h1><p class="lede small">Record each phase as written in the surgeon’s or provider’s protocol. PT Atlas never suggests timelines, restrictions or criteria.</p></div><form class="form" id="phaseForm"><fieldset class="panel"><legend>Phase</legend><div class="two">${field('name','Phase name *',ph.name,{type:'text',required:true,placeholder:'e.g. Phase 1'})}${field('timeframe','Timeframe',ph.timeframe,{type:'text',placeholder:'As written in your source'})}</div>${field('objectives','Objectives',ph.objectives)}${field('restrictions','Restrictions & precautions',ph.restrictions)}${field('criteria','Criteria to progress',ph.criteria)}</fieldset><fieldset class="panel"><legend>Linked interventions</legend>${options.length?`<div class="checks">${options.map(({x})=>`<label class="toggle"><input type="checkbox" name="interventionIds" value="${escapeHTML(x.id)}" ${chosen.has(x.id)?'checked':''}><span>${escapeHTML(x.name)}</span></label>`).join('')}</div>`:'<p class="placeholder">Interventions linked to this condition will appear here.</p>'}</fieldset><fieldset class="panel"><legend>Source</legend><div class="two">${field('source','Source / protocol name',ph.source,{type:'text',placeholder:'Provider protocol, guideline or citation'})}${field('sourceDate','Source date',ph.sourceDate,{type:'date'})}</div></fieldset><div class="actions sticky-actions"><button class="btn primary" type="submit">Save phase</button>${btn('Cancel','cancel-phase','ghost')}${ph.id?btn('Delete phase','delete-phase','danger','trash'):''}</div></form>`}
function showConditionTab(c,tab){view='condition';activeRegion=c.region;activeCondition=c.name;conditionTab=tab;phaseEdit=null}
async function savePhase(form){const c=conditionById(phaseEdit?.conditionId);if(!c)throw Error('Condition not found');const data=new FormData(form),old=phases.find(p=>p.id===phaseEdit.phaseId);const text=key=>String(data.get(key)||'');const list=phasesFor(c.id);const obj={...old,id:old?.id||uid(),conditionId:c.id,name:text('name').trim(),timeframe:text('timeframe'),objectives:text('objectives'),restrictions:text('restrictions'),criteria:text('criteria'),source:text('source'),sourceDate:text('sourceDate'),interventionIds:data.getAll('interventionIds').map(String),order:old?old.order:(list.length?Math.max(...list.map(p=>p.order||0))+1:0),updated:today()};if(!obj.name)throw Error('Each phase needs a name');await put('phases',obj);showConditionTab(c,'protocol');await reload();window.scrollTo(0,0);msg('Protocol phase saved locally')}
async function movePhase(id,delta){const ph=phases.find(p=>p.id===id);if(!ph)return;const list=phasesFor(ph.conditionId),i=list.indexOf(ph),j=i+delta;if(j<0||j>=list.length)return;[list[i],list[j]]=[list[j],list[i]];const tx=db.transaction('phases','readwrite');list.forEach((p,order)=>tx.objectStore('phases').put({...p,order}));await transactionDone(tx);await reload();document.querySelector(`[data-action="phase-${delta<0?'up':'down'}"][data-phase="${CSS.escape(id)}"]`)?.focus()}
function historyPanel(entityId){const list=revisionsFor(entityId).filter(r=>r.summary!=='Deleted');if(!list.length)return '';return `<section class="panel history"><h2>${icon('history',20)} Revision history</h2><ol class="revlist">${list.map(r=>`<li><div><b>${r.summary==='Edited'?'Version before edit':escapeHTML(r.summary==='Before restore'?'Version before restore':r.summary)}</b><span class="row-meta">${fmtDate(r.at)}</span></div><button type="button" class="btn ghost small" data-action="restore-revision" data-rev="${escapeHTML(r.id)}">Restore</button></li>`).join('')}</ol><p class="row-meta">Earlier versions are kept on this device, up to ${REVISION_LIMIT} per entry, and included in backups.</p></section>`}
function linkPanel(x){const list=linksFor(x.id);return `<div class="panel glance"><h2>${icon('link',18)} Condition links</h2><p class="row-meta">Use the same intervention for other conditions, with details specific to each.</p>${list.length?`<ul class="linklist">${list.map(l=>{const c=conditionById(l.conditionId);return `<li><div class="linklist-head"><button type="button" class="linkish" data-condition="${escapeHTML(c.name)}" data-c-region="${escapeHTML(c.region)}">${escapeHTML(c.name)}</button><span class="linklist-actions"><button type="button" class="iconbtn" data-action="edit-link" data-link="${escapeHTML(l.id)}" aria-label="Edit link to ${escapeHTML(c.name)}">${icon('edit',16)}</button><button type="button" class="iconbtn" data-action="remove-link" data-link="${escapeHTML(l.id)}" aria-label="Unlink ${escapeHTML(c.name)}">${icon('trash',16)}</button></span></div><span class="row-meta">${escapeHTML(c.region)}</span>${linkContext(l)}</li>`}).join('')}</ul>`:''}${btn('Link to a condition','link-condition','ghost small','link')}</div>`}
function linkEditor(){const x=items.find(i=>i.id===linkEdit?.interventionId);if(!x)return library();const l=links.find(k=>k.id===linkEdit.linkId)||{};const taken=new Set(linksFor(x.id).filter(k=>k.id!==l.id).map(k=>k.conditionId));const groups=regions.map(r=>{const cs=conditions.filter(c=>c.region===r&&!taken.has(c.id)).sort((a,b)=>a.name.localeCompare(b.name));return cs.length?`<optgroup label="${escapeHTML(r)}">${cs.map(c=>`<option value="${escapeHTML(c.id)}" ${c.id===l.conditionId?'selected':''}>${escapeHTML(c.name)}</option>`).join('')}</optgroup>`:''}).join('');return `<div class="page-head">${kicker('Condition link',x.region)}<h1>${l.id?'Edit condition link':'Link to a condition'}</h1><p class="lede small">Attach “${escapeHTML(x.name)}” to a condition and record what is specific to it. The intervention itself is not duplicated.</p></div><form class="form" id="linkForm"><fieldset class="panel"><legend>Condition</legend><div class="field"><label>Linked condition *</label><select name="conditionId" required>${groups}</select></div></fieldset><fieldset class="panel"><legend>Condition-specific details</legend>${field('dosage','Condition-specific dosage',l.dosage,{hint:'From your source for this condition. PT Atlas never suggests defaults.'})}${field('restrictions','Condition-specific restrictions',l.restrictions)}${field('notes','Condition-specific notes',l.notes)}</fieldset><div class="actions sticky-actions"><button class="btn primary" type="submit">Save link</button>${btn('Cancel','cancel-link','ghost')}</div></form>`}
async function saveLink(form){const x=items.find(i=>i.id===linkEdit?.interventionId);if(!x)throw Error('Intervention not found');const data=new FormData(form),old=links.find(k=>k.id===linkEdit.linkId);const conditionId=String(data.get('conditionId')||'');if(!conditionById(conditionId))throw Error('Choose a condition');if(links.some(k=>k.id!==old?.id&&k.interventionId===x.id&&k.conditionId===conditionId))throw Error('This intervention is already linked to that condition');await put('links',{...old,id:old?.id||uid(),interventionId:x.id,conditionId,dosage:String(data.get('dosage')||''),restrictions:String(data.get('restrictions')||''),notes:String(data.get('notes')||''),updated:today()});linkEdit=null;editId=x.id;view='detail';await reload();window.scrollTo(0,0);msg('Condition link saved locally')}
function collectionPanel(x){const inside=collections.filter(col=>colIds(col).includes(x.id));const others=collections.filter(col=>!colIds(col).includes(x.id)).sort((a,b)=>a.name.localeCompare(b.name));return `<div class="panel glance"><h2>${icon('collection',18)} Collections</h2>${inside.length?`<div class="chips">${inside.map(col=>`<button type="button" class="chip chip-link" data-collection="${escapeHTML(col.id)}">${escapeHTML(col.name)}</button>`).join('')}</div>`:'<p class="row-meta">Not in any collection yet.</p>'}${others.length?`<div class="inline-form"><label class="sr-only" for="collectionPick">Collection</label><select id="collectionPick">${others.map(col=>`<option value="${escapeHTML(col.id)}">${escapeHTML(col.name)}</option>`).join('')}</select>${btn('Add to collection','add-to-collection','ghost small')}</div>`:''}<button type="button" class="link-cta" data-action="new-collection">New collection${icon('chevron',16)}</button></div>`}
function collectionsView(){const list=[...collections].sort((a,b)=>a.name.localeCompare(b.name));return `<div class="page-head">${kicker('Curate')}<h1>Collections</h1><p class="lede small">Group interventions into ordered sets for a clinic session, a home-program draft or a teaching outline, then print them.</p><div class="actions">${btn('New collection','new-collection','primary','plus')}</div></div>${list.length?`<div class="tiles">${list.map(col=>`<button class="tile" data-collection="${escapeHTML(col.id)}" style="--hue:#527DFF"><span class="tile-icon">${icon('collection',26)}</span><span class="tile-body"><h3>${escapeHTML(col.name)}</h3><span class="tile-meta">${plural(colItems(col).length,'intervention')}</span></span><span class="tile-arrow">${icon('arrow',18)}</span></button>`).join('')}</div>`:empty('No collections yet.','Create a collection, then add interventions from their detail pages.')}`}
function printBlock(x){const rows=[['Purpose',x.purpose],['Setup & positioning',x.setup],['Instructions',x.instructions],['Dosage',x.dosage],['Equipment',x.equipment],['Progressions & regressions',x.progressions],['Precautions',x.precautions]].filter(([,v])=>v);return rows.length?`<dl class="print-dl">${rows.map(([t,v])=>`<div><dt>${t}</dt><dd>${escapeHTML(v)}</dd></div>`).join('')}</dl>`:''}
function collectionPage(){const col=collections.find(c=>c.id===activeCollection);if(!col)return collectionsView();const list=colItems(col);return `<div class="page-head"><nav class="breadcrumb no-print" aria-label="Breadcrumb"><button data-nav="collections">Collections</button>${icon('chevron',14)}<span>${escapeHTML(col.name)}</span></nav>${kicker('Collection')}<h1>${escapeHTML(col.name)}</h1>${col.description?`<p class="lede small">${escapeHTML(col.description)}</p>`:''}<div class="actions no-print">${btn('Print','print','primary','print')}${btn('Edit collection','edit-collection','ghost','edit')}${btn('Delete collection','delete-collection','danger','trash')}</div></div>${list.length?`<ol class="collection-list">${list.map((x,i)=>`<li><span class="num">${pad(i+1)}</span><div class="collection-item"><div class="no-print">${itemCard(x)}</div><div class="print-only"><h3>${escapeHTML(x.name)}</h3><p class="row-meta">${escapeHTML(x.region)}${x.condition?' · '+escapeHTML(x.condition):''}</p>${printBlock(x)}${printImages(x)}</div></div><div class="order no-print"><button type="button" class="iconbtn" data-action="col-up" data-item="${escapeHTML(x.id)}" aria-label="Move ${escapeHTML(x.name)} up" ${i===0?'disabled':''}>${icon('up')}</button><button type="button" class="iconbtn" data-action="col-down" data-item="${escapeHTML(x.id)}" aria-label="Move ${escapeHTML(x.name)} down" ${i===list.length-1?'disabled':''}>${icon('down')}</button><button type="button" class="iconbtn" data-action="col-remove" data-item="${escapeHTML(x.id)}" aria-label="Remove ${escapeHTML(x.name)} from collection">${icon('trash')}</button></div></li>`).join('')}</ol>`:empty('This collection is empty.','Open any intervention and use “Add to collection”.')}<p class="fineprint print-only">Printed from PT Atlas on ${today()}. Content is user-entered; verify against patient-specific orders. Contains no patient information.</p>`}
function collectionEditor(){const col=collections.find(c=>c.id===collectionEditId)||{};return `<div class="page-head">${kicker('Curate')}<h1>${col.id?'Edit':'New'} collection</h1></div><form class="form" id="collectionForm"><fieldset class="panel"><legend>Collection</legend>${field('name','Collection name *',col.name,{type:'text',required:true,placeholder:'e.g. Hip strengthening set'})}${field('description','Description',col.description,{placeholder:'What this set is for (no patient information)'})}</fieldset><div class="actions sticky-actions"><button class="btn primary" type="submit">Save collection</button>${btn('Cancel','cancel-collection','ghost')}</div></form>`}
async function saveCollection(form){const data=new FormData(form),old=collections.find(c=>c.id===collectionEditId);const name=String(data.get('name')||'').trim();if(!name)throw Error('Name the collection');const ids=[...(old?colIds(old):[])];if(pendingCollectionAdd&&!ids.includes(pendingCollectionAdd)&&items.some(x=>x.id===pendingCollectionAdd))ids.push(pendingCollectionAdd);const obj={...old,id:old?.id||uid(),name,description:String(data.get('description')||''),interventionIds:ids,updated:today()};await put('collections',obj);pendingCollectionAdd=null;collectionEditId=null;activeCollection=obj.id;view='collection';await reload();window.scrollTo(0,0);msg('Collection saved locally')}
async function updateCollection(col,ids){await put('collections',{...col,interventionIds:ids,updated:today()});await reload()}
function recentlyDeleted(){const seen=new Set();const list=revisions.filter(r=>r.summary==='Deleted'&&!(r.entityType==='condition'?conditions:items).some(x=>x.id===r.entityId)).sort((a,b)=>b.at.localeCompare(a.at)).filter(r=>!seen.has(r.entityId)&&seen.add(r.entityId));return `<section class="panel"><h2>Recently deleted</h2><p class="muted">Deleted interventions and conditions can be restored with their condition links and protocol phases.</p>${list.length?`<ul class="revlist">${list.map(r=>`<li><div><b>${escapeHTML(r.entityName||'Untitled')}</b><span class="row-meta">${r.entityType==='condition'?'Condition':'Intervention'} · deleted ${fmtDate(r.at)}</span></div><button type="button" class="btn ghost small" data-action="restore-revision" data-rev="${escapeHTML(r.id)}" aria-label="Restore ${escapeHTML(r.entityName||'entry')}">Restore</button></li>`).join('')}</ul>`:'<p class="row-meta">Nothing deleted recently.</p>'}</section>`}
async function restoreRevision(id){
 const r=revisions.find(v=>v.id===id),snap=r&&readSnapshot(r);if(!snap)throw Error('This version cannot be restored.');
 const isCondition=r.entityType==='condition',store=isCondition?'conditions':'interventions',record=snap.record;
 if(typeof record.id!=='string'||typeof record.name!=='string'||!regions.includes(record.region))throw Error('This version cannot be restored.');
 const current=(isCondition?conditions:items).find(x=>x.id===record.id);
 if(isCondition&&conditions.some(c=>c.id!==record.id&&c.name===record.name&&c.region===record.region))throw Error('Another condition in this region already uses that name. Rename it first.');
 if(!confirm(current?`Restore this earlier version of “${record.name}”? The current version stays in history.`:`Restore “${record.name}”?`))return;
 const tx=db.transaction(['interventions','conditions','links','phases','revisions'],'readwrite');
 if(current)addRevision(tx,r.entityType,current,'Before restore');
 tx.objectStore(store).put({...record,updated:today()});
 if(isCondition&&current&&(current.name!==record.name||current.region!==record.region))for(const item of items.filter(i=>i.region===current.region&&i.condition===current.name))tx.objectStore('interventions').put({...item,region:record.region,condition:record.name});
 for(const l of Array.isArray(snap.links)?snap.links:[])if(l&&typeof l.id==='string'&&typeof l.interventionId==='string'&&typeof l.conditionId==='string')tx.objectStore('links').put(l);
 for(const ph of Array.isArray(snap.phases)?snap.phases:[])if(ph&&typeof ph.id==='string'&&typeof ph.conditionId==='string')tx.objectStore('phases').put(ph);
 await transactionDone(tx);
 if(isCondition){view='condition';activeRegion=record.region;activeCondition=record.name;conditionTab='overview'}else{view='detail';editId=record.id}
 query='';await reload();window.scrollTo(0,0);msg('Restored “'+record.name+'”');
}
async function knowledgeAction(a,el){
 const x=items.find(i=>i.id===editId),c=conditions.find(k=>k.name===activeCondition&&k.region===activeRegion),col=collections.find(k=>k.id===activeCollection);
 switch(a){
  case 'review-queue':setView('library');filters.status=items.some(i=>statusOf(i)==='unreviewed')||!items.some(i=>reviewDue(i))?'unreviewed':'due';render();return true;
  case 'collections':setView('collections');return true;
  case 'restore-revision':await restoreRevision(el.dataset.rev);return true;
  case 'link-condition':linkEdit={interventionId:editId,linkId:null};view='link-editor';render();window.scrollTo(0,0);return true;
  case 'edit-link':linkEdit={interventionId:editId,linkId:el.dataset.link};view='link-editor';render();window.scrollTo(0,0);return true;
  case 'cancel-link':linkEdit=null;view='detail';render();return true;
  case 'remove-link':{const l=links.find(k=>k.id===el.dataset.link);if(l&&confirm('Remove this condition link? The intervention and condition are kept.')){await remove('links',l.id);await reload();msg('Condition link removed')}return true}
  case 'add-phase':if(c){phaseEdit={conditionId:c.id,phaseId:null};view='phase-editor';render();window.scrollTo(0,0)}return true;
  case 'edit-phase':if(c){phaseEdit={conditionId:c.id,phaseId:el.dataset.phase};view='phase-editor';render();window.scrollTo(0,0)}return true;
  case 'cancel-phase':{const pc=conditionById(phaseEdit?.conditionId);if(pc)showConditionTab(pc,'protocol');render();return true}
  case 'delete-phase':{const pc=conditionById(phaseEdit?.conditionId);if(pc&&confirm('Delete this protocol phase?')){await remove('phases',phaseEdit.phaseId);showConditionTab(pc,'protocol');await reload();msg('Protocol phase deleted')}return true}
  case 'phase-up':case 'phase-down':await movePhase(el.dataset.phase,a==='phase-up'?-1:1);return true;
  case 'new-collection':pendingCollectionAdd=view==='detail'?editId:null;collectionEditId=null;view='collection-editor';render();window.scrollTo(0,0);return true;
  case 'edit-collection':collectionEditId=activeCollection;pendingCollectionAdd=null;view='collection-editor';render();return true;
  case 'cancel-collection':{const back=pendingCollectionAdd;pendingCollectionAdd=null;if(back){editId=back;view='detail'}else view=collectionEditId?'collection':'collections';collectionEditId=null;render();return true}
  case 'delete-collection':if(col&&confirm('Delete this collection? Its interventions stay in your library.')){await remove('collections',col.id);setView('collections');await reload();msg('Collection deleted')}return true;
  case 'add-to-collection':{const target=collections.find(k=>k.id===$('#collectionPick')?.value);if(target&&x){await updateCollection(target,[...colIds(target),x.id]);msg('Added to '+target.name)}return true}
  case 'col-up':case 'col-down':case 'col-remove':{if(!col)return true;const ids=colIds(col).filter(id=>items.some(i=>i.id===id)),i=ids.indexOf(el.dataset.item);if(i<0)return true;if(a==='col-remove')ids.splice(i,1);else{const j=i+(a==='col-up'?-1:1);if(j<0||j>=ids.length)return true;[ids[i],ids[j]]=[ids[j],ids[i]]}await updateCollection(col,ids);if(a!=='col-remove')document.querySelector(`[data-action="${a}"][data-item="${CSS.escape(el.dataset.item)}"]`)?.focus();return true}
  case 'print':window.print();return true;
  case 'google-sync':await startGoogleSync(el);return true;
  case 'google-connect':await startGoogleConnect(el);return true;
  case 'clear-google':try{localStorage.removeItem('atlas-google-config')}catch{}disconnectGoogle();render();googleStatus('Browser setup cleared. '+googleSetupText());return true;
  case 'commit-sync':await commitGoogleSync();return true;
  case 'cancel-sync':syncBatch=null;setView('import');return true;
  case 'add-region':await addRegion();return true;
  case 'rename-region':await renameRegion(el.dataset.rid);return true;
  case 'delete-region':await deleteRegion(el.dataset.rid);return true;
  case 'remove-media':{const m=mediaList.find(k=>k.id===el.dataset.media);if(m&&confirm(`Remove the attachment “${m.name}”?`)){await remove('media',m.id);await reload();refreshStorage();msg('Attachment removed')}return true}
  case 'purge-media':{const orphans=orphanMedia();if(orphans.length&&confirm(`Permanently remove ${plural(orphans.length,'attachment')} that belong to deleted interventions? Restoring those interventions later will not bring them back.`)){const tx=db.transaction('media','readwrite');for(const m of orphans)tx.objectStore('media').delete(m.id);await transactionDone(tx);await reload();refreshStorage();msg('Removed '+plural(orphans.length,'attachment'))}return true}
 }
 return false;
}

// ——— Custom body regions ———
function regionsPanel(){return `<section class="panel"><h2>Body regions</h2><p class="muted">The ten standard regions are fixed. Add your own specialties, such as Pelvic Health or Pediatrics. A custom region can be renamed, or deleted once nothing uses it.</p>${customRegions.length?`<ul class="revlist region-list">${[...customRegions].sort((a,b)=>a.name.localeCompare(b.name)).map(r=>{const used=conditions.filter(c=>c.region===r.name).length+items.filter(x=>x.region===r.name).length;return `<li style="--hue:${r.hue}"><span class="tile-icon small">${regionIcon(r.name,18)}</span><label class="sr-only" for="rname-${escapeHTML(r.id)}">Name for ${escapeHTML(r.name)}</label><input id="rname-${escapeHTML(r.id)}" class="region-input" value="${escapeHTML(r.name)}" maxlength="60"><span class="row-meta">${plural(used,'entry')}</span><button type="button" class="btn ghost small" data-action="rename-region" data-rid="${escapeHTML(r.id)}">Rename</button><button type="button" class="iconbtn" data-action="delete-region" data-rid="${escapeHTML(r.id)}" aria-label="Delete region ${escapeHTML(r.name)}" ${used?'disabled':''}>${icon('trash',16)}</button></li>`}).join('')}</ul>`:''}<div class="inline-form"><label class="sr-only" for="newRegion">New body region name</label><input id="newRegion" class="region-input" maxlength="60" placeholder="New region, e.g. Pelvic Health">${btn('Add region','add-region','ghost small','plus')}</div></section>`}
function regionNameError(name,exceptId){if(!name)return 'Enter a region name.';if(name.length>60)return 'Use 60 characters or fewer.';if(BUILTIN_REGIONS.some(r=>r.toLowerCase()===name.toLowerCase())||customRegions.some(r=>r.id!==exceptId&&r.name.toLowerCase()===name.toLowerCase()))return 'A region with that name already exists.';return ''}
async function addRegion(){const name=($('#newRegion')?.value||'').trim(),error=regionNameError(name);if(error)throw Error(error);await put('regions',{id:uid(),name,hue:customHues[customRegions.length%customHues.length],created:today()});await reload();msg('Added region '+name);$('#newRegion')?.focus()}
async function renameRegion(id){const r=customRegions.find(k=>k.id===id);if(!r)return;const name=($('#rname-'+CSS.escape(id))?.value||'').trim();if(name===r.name)return;const error=regionNameError(name,id);if(error)throw Error(error);
 const tx=db.transaction(['regions','conditions','interventions'],'readwrite');tx.objectStore('regions').put({...r,name});for(const c of conditions.filter(c=>c.region===r.name))tx.objectStore('conditions').put({...c,region:name});for(const x of items.filter(x=>x.region===r.name))tx.objectStore('interventions').put({...x,region:name});await transactionDone(tx);await reload();msg('Renamed region to '+name)}
async function deleteRegion(id){const r=customRegions.find(k=>k.id===id);if(!r)return;if(conditions.some(c=>c.region===r.name)||items.some(x=>x.region===r.name))throw Error('Move or delete the conditions and interventions in this region first.');if(confirm(`Delete the region “${r.name}”?`)){await remove('regions',id);await reload();msg('Region deleted')}}

// ——— Attachments ———
const fmtSize=n=>n<1048576?Math.max(1,Math.round(n/1024))+' KB':(n/1048576).toFixed(1)+' MB';
function objURL(m){const url=URL.createObjectURL(m.blob);objectURLs.push(url);return url}
const mediaFor=id=>mediaList.filter(m=>m.interventionId===id).sort((a,b)=>(a.created||'').localeCompare(b.created||''));
const orphanMedia=()=>mediaList.filter(m=>!items.some(x=>x.id===m.interventionId));
function attachmentsPanel(x){const list=mediaFor(x.id);return `<section class="panel attachments"><h2>${icon('doc',20)} Attachments</h2><p class="row-meta">Images (PNG, JPEG, GIF, WebP) and PDFs up to ${fmtSize(MEDIA_LIMIT)} each, stored on this device and included in backups. Never attach anything that identifies a patient.</p>${list.length?`<ul class="media-grid">${list.map(m=>{const url=objURL(m),isImage=m.type.startsWith('image/');return `<li>${isImage?`<a href="${url}" target="_blank" rel="noopener" class="media-thumb"><img src="${url}" alt="${escapeHTML(m.name)}" loading="lazy"></a>`:`<a href="${url}" target="_blank" rel="noopener" class="media-thumb pdf">${icon('doc',30)}<span>PDF</span></a>`}<div class="media-meta"><span class="media-name" title="${escapeHTML(m.name)}">${escapeHTML(m.name)}</span><span class="row-meta">${fmtSize(m.size)}</span></div><button type="button" class="iconbtn" data-action="remove-media" data-media="${escapeHTML(m.id)}" aria-label="Remove attachment ${escapeHTML(m.name)}">${icon('trash',16)}</button></li>`}).join('')}</ul>`:''}<label class="filepick-btn btn ghost small">${icon('plus',16)}Add images or PDFs<input type="file" id="mediaFile" accept="${ALLOWED_TYPES.join(',')}" multiple class="sr-only"></label><p class="row-meta" id="mediaStatus" role="status" aria-live="polite"></p></section>`}
async function addAttachments(files){const status=text=>{const el=$('#mediaStatus');if(el)el.textContent=text};const id=editId;if(!files.length||!items.some(x=>x.id===id))return;const added=[],skipped=[];
 for(const file of files){if(file.size>MEDIA_LIMIT){skipped.push(file.name+' (over '+fmtSize(MEDIA_LIMIT)+')');continue}const type=sniffType(new Uint8Array(await file.slice(0,16).arrayBuffer()));if(!type){skipped.push(file.name+' (not a PNG, JPEG, GIF, WebP or PDF)');continue}added.push({id:uid(),interventionId:id,name:file.name.slice(0,200),type,size:file.size,created:new Date().toISOString(),blob:file.slice(0,file.size,type)})}
 if(added.length){try{const tx=db.transaction('media','readwrite');for(const m of added)tx.objectStore('media').put(m);await transactionDone(tx)}catch(error){status('Could not save attachments: '+(error?.name==='QuotaExceededError'?'this device is out of storage space for PT Atlas.':error.message));return}await reload();refreshStorage()}
 msg(added.length?`Added ${plural(added.length,'attachment')}`:'No attachments added');if(skipped.length)status('Skipped: '+skipped.join('; '))}
function attachmentsSummary(){const total=mediaList.reduce((n,m)=>n+(m.size||0),0),orphans=orphanMedia();return `<section class="panel"><h2>Attachments</h2><p class="muted">${mediaList.length?`${plural(mediaList.length,'attachment')} using ${fmtSize(total)}.`:'No attachments yet.'} ${orphans.length?`${plural(orphans.length,'attachment')} (${fmtSize(orphans.reduce((n,m)=>n+(m.size||0),0))}) belong to deleted interventions and return if you restore them.`:''}</p>${orphans.length?`<div class="actions">${btn('Remove attachments of deleted entries','purge-media','ghost','trash')}</div>`:''}</section>`}
function printImages(x){const list=mediaFor(x.id).filter(m=>m.type.startsWith('image/'));return list.length?`<div class="print-media">${list.map(m=>`<img src="${objURL(m)}" alt="${escapeHTML(m.name)}">`).join('')}</div>`:''}
async function exportBackup(){const media=[];for(const m of mediaList)media.push({id:m.id,interventionId:m.interventionId,name:m.name,type:m.type,created:m.created||'',data:bytesToBase64(new Uint8Array(await m.blob.arrayBuffer()))});
 download(JSON.stringify(backupPayload({regions:customRegions,interventions:items,conditions,links,phases,collections,revisions,media}),null,2),'pt-atlas-backup-'+today()+'.json')}

// ——— Google account and one-way Docs re-sync ———
let syncBatch=null;
function requireGoogleConfig(){const active=activeGoogleConfig();if(!active)validateGoogleConfig({});return active.config}
function googleAccountPanel(){const active=activeGoogleConfig(),connected=googleConnected();return `<section class="panel"><h2>Google account</h2><p class="muted">${googleSetupText()}</p><p class="row-meta" id="googleAccountStatus" role="status" aria-live="polite">${connected?'Connected for this session. Access expires automatically within an hour; reconnecting does not ask for consent again.':'Not connected. Signing in is optional; your library works without it.'}</p><div class="actions">${active?btn(connected?'Reconnect Google':'Connect Google account','google-connect','primary'):''}${connected?btn('Disconnect Google','disconnect-google','ghost'):''}${btn('Google import & sync','import','ghost','import')}</div><p class="row-meta">PT Atlas asks only for access to the Google Docs you pick (the drive.file permission). It can’t see the rest of your Drive and never edits your documents. Tokens stay in memory and are never saved or backed up.</p></section>`}
async function ensureGoogleLibraries(again){if(googleReady())return true;googleStatus('Loading Google connection…');await prepareGoogle();googleStatus(`Google connection ready. Click ${again} again to sign in.`);return false}
async function startGoogleConnect(button){try{if(!navigator.onLine)throw Error('Connecting to Google needs an internet connection.');const config=requireGoogleConfig();button.disabled=true;if(!await ensureGoogleLibraries(button.textContent.trim()))return;await connectGoogle(config);render();googleStatus('Connected to Google for this session.');msg('Connected to Google')}catch(error){googleStatus('Google connection failed: '+error.message)}finally{if(button.isConnected)button.disabled=false}}
async function startGoogleSync(button){
 try{
  if(!navigator.onLine)throw Error('Checking Google Docs needs an internet connection.');
  const config=requireGoogleConfig();button.disabled=true;
  if(!await ensureGoogleLibraries('Check imported Docs for updates'))return;
  const bearer=await googleToken(config);googleStatus('Checking linked Google Docs…');
  const linked=linkedGoogleEntries(),results=await checkGoogleUpdates(linked,bearer);
  const changed=results.filter(r=>r.status==='changed'),unavailable=results.filter(r=>r.status==='unavailable');
  const unreadable=unavailable.length?` ${plural(unavailable.length,'document')} couldn’t be read (deleted, in the trash, or no longer shared with PT Atlas); those entries are unchanged.`:'';
  if(!changed.length){googleStatus(`Up to date: ${plural(results.length-unavailable.length,'linked Google Doc')} checked, no changes since import.`+unreadable);return}
  const docs=[];for(let i=0;i<changed.length;i+=MAX_DOCS)docs.push(...await readGoogleDocuments(changed.slice(i,i+MAX_DOCS).map(r=>({id:r.id})),bearer));
  syncBatch={unreadable,docs:docs.map(doc=>{const entries=linked.filter(x=>x.sourceDocumentId===doc.metadata.sourceDocumentId);return {doc,entries,items:syncPlan(entries,doc.text,doc.metadata.documentTitle,{pristine})}})};
  view='sync-review';query='';render();window.scrollTo(0,0);
 }catch(error){googleStatus('Google sync failed: '+error.message)}
 finally{if(button.isConnected)button.disabled=false}
}
function diffHTML(diff){const out=[];let run=[];const flush=()=>{if(run.length>6)out.push(...run.slice(0,2),`<span class="d-skip">… ${plural(run.length-4,'unchanged line')} …</span>`,...run.slice(-2));else out.push(...run);run=[]};for(const line of diff){const text=escapeHTML(line.text)||' ';if(line.type==='same')run.push(`<span class="d-same">  ${text}</span>`);else{flush();out.push(line.type==='add'?`<ins class="d-add">+ ${text}</ins>`:`<del class="d-del">− ${text}</del>`)}}flush();return `<pre class="diff">${out.join('\n')}</pre>`}
function syncItem(item,di,ii){const name=escapeHTML(item.entry?.name||item.section?.name);const field=`sync-${di}-${ii}`;
 if(item.kind==='changed')return `<div class="sync-item"><h3>${name}</h3>${item.edited?`<div class="warning">${icon('alert',18)}<span>You edited this entry after importing it. “Replace” overwrites those edits; the current version stays in revision history.</span></div>`:''}<p class="row-meta">Changes since your last import (<ins class="d-add">+ added</ins>, <del class="d-del">− removed</del>):</p>${diffHTML(item.diff)}<div class="field"><label for="${field}">What to do with “${name}”</label><select id="${field}" name="${field}"><option value="skip">Skip for now (ask again next check)</option><option value="replace">Replace the imported text with the new version</option><option value="append">Append the new version to my notes</option></select></div></div>`;
 if(item.kind==='new')return `<div class="sync-item"><h3>New section: ${name}</h3><div class="sync-preview">${md(item.section.notes.slice(0,1200))}</div><div class="field"><label for="${field}">What to do with the new section “${name}”</label><select id="${field}" name="${field}"><option value="skip">Don’t add</option><option value="create">Add as a new entry (marked Needs review)</option></select></div></div>`;
 if(item.kind==='missing')return `<p class="row-meta sync-item">“${name}” is no longer a section in this document. Your entry is unchanged.</p>`;
 return `<p class="row-meta sync-item">“${name}” has no text changes.</p>`}
function syncReview(){const b=syncBatch;if(!b)return importer();return `<div class="page-head">${kicker('Google Docs sync')}<h1>Review document updates</h1><p class="lede small">These Google Docs changed after you imported them. Nothing in your library changes until you apply. Updated entries are marked Needs review, and replaced versions stay in revision history.</p>${b.unreadable?`<p class="row-meta">${escapeHTML(b.unreadable.trim())}</p>`:''}</div><form id="syncForm" class="form">${b.docs.map((d,di)=>`<section class="panel"><div class="draft-head"><span class="num">${pad(di+1)}</span><div><h2>${escapeHTML(d.doc.metadata.documentTitle)}</h2><p class="row-meta">Changed in Google ${fmtDate(d.doc.metadata.fileModifiedAt)} · <a href="${escapeHTML(d.doc.metadata.source)}" target="_blank" rel="noopener noreferrer">Open in Google Docs</a></p></div></div>${d.items.map((item,ii)=>syncItem(item,di,ii)).join('')}</section>`).join('')}<div class="actions sticky-actions">${btn('Apply selected updates','commit-sync','primary')}${btn('Cancel','cancel-sync','ghost')}</div></form>`}
async function commitGoogleSync(){
 const b=syncBatch;if(!b)return;const data=new FormData($('#syncForm')),now=new Date().toISOString(),writes=[],revised=[];let replaced=0,appended=0,created=0;
 b.docs.forEach((d,di)=>{const meta=d.doc.metadata,history={documentTitle:meta.documentTitle,source:meta.source,fileName:meta.fileName,fileModifiedAt:meta.fileModifiedAt,sourceDocumentId:meta.sourceDocumentId,importedAt:now,type:'sync'};
  const synced=(entry,changes)=>({...entry,...changes,sourceModifiedAt:meta.fileModifiedAt,importHistory:JSON.stringify([...readImportHistory(entry.importHistory),history])});
  d.items.forEach((item,ii)=>{const decision=data.get(`sync-${di}-${ii}`);const current=item.entry&&items.find(x=>x.id===item.entry.id);
   if(item.kind==='changed'&&current&&decision==='replace'){revised.push(current);writes.push(synced(current,{...remapped(current,item.section.notes),reviewStatus:'unreviewed',updated:today()}));replaced++}
   else if(item.kind==='changed'&&current&&decision==='append'){revised.push(current);writes.push(synced(current,{notes:[current.notes,`Updated from “${meta.documentTitle}” (Google Docs) on ${today()}:`,item.section.notes].filter(Boolean).join('\n\n'),sourceText:item.section.notes,reviewStatus:'unreviewed',updated:today()}));appended++}
   // Unchanged entries and entries whose section left the document are marked as checked; their content is untouched.
   else if((item.kind==='unchanged'||item.kind==='missing')&&current&&(current.sourceModifiedAt||'')<meta.fileModifiedAt)writes.push({...current,sourceModifiedAt:meta.fileModifiedAt});
   else if(item.kind==='new'&&decision==='create'){const base=d.entries[0];const draft=prepareDraft({name:item.section.name,region:base.region,condition:base.condition||'',notes:item.section.notes});writes.push(importRecord({...draft,condition:draft.condition||base.condition||''},{...meta,id:uid(),importedAt:now}));created++}
  })});
 if(replaced+appended+created&&!confirm(`Apply ${plural(replaced,'replacement')}, ${plural(appended,'append')} and ${plural(created,'new entry')}? Current versions are kept in revision history.`))return;
 if(writes.length){const tx=db.transaction(['interventions','revisions'],'readwrite');for(const old of revised)addRevision(tx,'intervention',old,'Before Google sync');for(const record of writes)tx.objectStore('interventions').put(record);await transactionDone(tx)}
 syncBatch=null;view='library';await reload();window.scrollTo(0,0);msg(replaced+appended+created?`Applied Google Docs updates: ${plural(replaced+appended,'entry')} updated, ${plural(created,'new entry')}.`:'No content updates applied.');
}

// ——— Label matching (deterministic, on-device) ———
function mapLabelsOn(){return readSetting('atlas-map-labels','on')!=='off'}
// Splits a draft's text into labelled fields when enabled; the original text is kept as sourceText for provenance and sync.
function prepareDraft(draft){const sourceText=draft.notes;if(!mapLabelsOn())return {...draft,sourceText,fields:{}};const {fields,notes}=mapFields(sourceText,{title:draft.name,categories});const condition=fields.condition;delete fields.condition;return {...draft,sourceText,notes,fields,condition:draft.condition||condition||''}}
function draftFields(draft,index){const keys=Object.keys(draft.fields||{});if(!keys.length)return '';return `<fieldset class="mapped"><legend>Fields found from labels</legend><p class="row-meta">Matched by label only. Edit or clear anything that landed in the wrong place.</p>${keys.map(key=>`<div class="field"><label>${FIELD_NAMES[key]}</label>${key==='category'?`<select name="f-${key}-${index}">${categories.map(c=>`<option ${c===draft.fields[key]?'selected':''}>${escapeHTML(c)}</option>`).join('')}</select>`:key==='tags'?`<input name="f-${key}-${index}" value="${escapeHTML(draft.fields[key])}">`:`<textarea name="f-${key}-${index}">${escapeHTML(draft.fields[key])}</textarea>`}</div>`).join('')}</fieldset>`}
function readDraftFields(data,index){const fields={};for(const key of MAPPABLE){if(key==='condition')continue;const value=data.get(`f-${key}-${index}`);if(typeof value==='string'&&value.trim()&&(key!=='category'||categories.includes(value)))fields[key]=value}return fields}
// An entry is "pristine" when its fields and notes still equal what label matching produces from the imported text.
function pristine(entry){const base=typeof entry.sourceText==='string'?entry.sourceText:null;if(base===null)return true;if(!Array.isArray(entry.mappedFields))return (entry.notes||'')===base;const m=mapFields(base,{title:entry.name,categories});delete m.fields.condition;for(const key of new Set([...entry.mappedFields,...Object.keys(m.fields)]))if(key!=='condition'&&(entry[key]||'')!==(m.fields[key]||''))return false;return (entry.notes||'')===m.notes}
// Replacement text for sync: re-run label matching for entries imported that way (or when matching is on).
function remapped(entry,text){if(!Array.isArray(entry.mappedFields)&&!mapLabelsOn())return {notes:text,sourceText:text};const {fields,notes}=mapFields(text,{title:entry.name,categories});delete fields.condition;const cleared=Object.fromEntries((entry.mappedFields||[]).filter(k=>!(k in fields)&&k!=='condition').map(k=>[k,'']));return {...cleared,...fields,notes,sourceText:text,mappedFields:Object.keys(fields)}}
